/// Given a vector of complex numbers `arr` (each holding 32‐bit integer `re` and `im`),
/// and a positive integer tolerance `tol`, returns
/// - a new vector where every `im` is zeroed out if *all* imaginary parts are “close to zero”
///   (i.e. `|im| <= tol * MACHINE_EPS`), or
/// - the original vector unchanged otherwise.
///
/// MACHINE_EPS is fixed at 2.
fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Fixed machine epsilon
    const MACHINE_EPS: i32 = 2;

    // Compute threshold in a wider type to avoid overflow on abs/min‐value.
    let threshold = (tol as i64) * (MACHINE_EPS as i64);

    // Check if *all* imaginary parts satisfy |im| <= threshold
    let all_close = arr.iter()
        .all(|c| (c.im as i64).abs() <= threshold);

    if all_close {
        // Zero out all imaginary parts
        arr.into_iter()
           .map(|c| Complex { re: c.re, im: 0 })
           .collect()
    } else {
        // Return the original vector unchanged
        arr
    }
}